function evidence = f90_xfluid08_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XFLUID08_EXTRACT_CANDIDATE_EVIDENCE Candidate fuel-system replay.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot,sharedRoot]=localRoots("F90-XFLUID-08");
addpath(sharedRoot,"-begin");cleanup=onCleanup(@()rmpath(sharedRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
profileFile=fullfile(taskRoot,string(official.simulation.native_profile_file));
assert(isfile(profileFile)&&strcmpi(localFilePresence(profileFile), ...
    "present"), ...
    "SimuVerity:UnifiedOutput:EvaluatorContract", ...
    "Pinned official command fixture is missing or has the wrong binding.");
spec=struct("schema","simuverity.f90-xfluid08-evidence.v1", ...
    "task_id","F90-XFLUID-08","scenarios",official.scenarios, ...
    "output_contract",localOutputs, ...
    "input_builder",@(s,~)localInputs(s,profileFile, ...
        double(official.simulation.stop_time_s)), ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@(~,~)double(official.simulation.stop_time_s), ...
    "postprocess",@localPostprocess,"static_audit",@localAudit, ...
    "evidence_sample_s",1.0);
evidence=simuverity_run_candidate_evidence(candidatePath,outDir,spec);
end
function rows=localOutputs
rows=localRows(["pump_speed_state","tank_fuel_state","transfer_hydraulics", ...
    "engine_feed_state","pump_power_state"],[8 4 8 2 8]);
end
function inputs=localInputs(s,profileFile,stopTime)
try
    command=localProfile(profileFile,s.native_profile,stopTime);
catch ME
    if string(ME.identifier)== ...
            "SimuVerity:UnifiedOutput:EvaluatorContract"
        rethrow(ME)
    end
    error("SimuVerity:UnifiedOutput:EvaluatorContract", ...
        "Pinned official command fixture normalization failed: %s", ...
        string(ME.identifier));
end
inputs=struct("flight_fuel_command",command, ...
    "initial_fuel_volume_m3",[double(s.wing_initial_volume_m3), ...
    double(s.wing_initial_volume_m3),double(s.center_initial_volume_m3)]);
end
function requested=localRequested(s,~),requested=rmfield(s,"id");end
function value=localProfile(profileFile,profile,stopTime)
profile=string(profile);
payload=load(profileFile,char(profile));
fields=string(fieldnames(payload));
index=find(strcmpi(fields,profile),1);
assert(~isempty(index),"SimuVerity:UnifiedOutput:EvaluatorContract", ...
        "Pinned command profile %s is missing.",profile);
dataset=payload.(char(fields(index)));
assert(isa(dataset,"Simulink.SimulationData.Dataset") && ...
    numElements(dataset)>=6, ...
    "SimuVerity:UnifiedOutput:EvaluatorContract", ...
    "Pinned command profile %s is not a six-signal Dataset.",profile);
series=cell(6,1);allTime=[0;stopTime];
for channel=1:6
    element=dataset{channel};
    if isprop(element,"Values"),element=element.Values;end
    assert(isa(element,"timeseries"), ...
        "SimuVerity:UnifiedOutput:EvaluatorContract", ...
        "Profile %s channel %d is not Timeseries.",profile,channel);
    t=double(element.Time(:));data=double(element.Data);
    data=reshape(data,numel(t),[]);
    assert(size(data,2)==1&&numel(t)>=1&&all(isfinite(t))&& ...
        all(isfinite(data),"all")&&all(diff(t)>=0), ...
        "SimuVerity:UnifiedOutput:EvaluatorContract", ...
        "Profile %s channel %d is invalid.",profile,channel);
    [t,data]=localNormalizeStepSeries(t,data,stopTime);
    series{channel}=struct("time",t,"data",data);
    allTime=[allTime;t]; %#ok<AGROW>
end
grid=unique(allTime(allTime>=0&allTime<=stopTime),"sorted");
commands=zeros(numel(grid),6);
for channel=1:6
    commands(:,channel)=interp1(series{channel}.time, ...
        series{channel}.data,grid,"previous","extrap");
end
value=timeseries(commands,grid);
end
function [time,data]=localNormalizeStepSeries(time,data,stopTime)
% Signal Editor fixtures may encode a step with duplicate timestamps or a
% single constant sample. Normalize evaluator-owned data to a strict,
% full-run zero-order-hold series before presenting it to the candidate.
if numel(time)==1
    time=[0;stopTime];data=repmat(data(1,:),2,1);return
end
[time,keep]=unique(time,"last");data=data(keep,:);
if time(1)>0,time=[0;time];data=[data(1,:);data];end
if time(end)<stopTime,time=[time;stopTime];data=[data;data(end,:)];end
end
function row=localPostprocess(row,outputs,scenario,~)
t=double(outputs.time_s(:));pump=double(outputs.pump_speed_state);
tank=double(outputs.tank_fuel_state);transfer=double(outputs.transfer_hydraulics);
feed=double(outputs.engine_feed_state);power=double(outputs.pump_power_state);
command=pump(:,1:2:end);actual=pump(:,2:2:end);
flow=transfer(:,1:4);pressure=transfer(:,5:8);
shaft=power(:,1:4);hydraulic=power(:,5:8);
late=t>=max(0.9*t(end),t(end)-300);
nrmse=zeros(1,4);correlation=zeros(1,4);ranges=zeros(1,4);
reverse=zeros(1,4);efficiency=zeros(1,4);
for k=1:4
    active=command(:,k)>=max(300,0.1*max(command(:,k)));
    if nnz(active)<10,active=true(size(t));end
    nrmse(k)=sqrt(mean((actual(active,k)-command(active,k)).^2))/ ...
        max(sqrt(mean(command(active,k).^2)),300);
    correlation(k)=localCorr(command(:,k),actual(:,k));
    ranges(k)=max(actual(:,k))-min(actual(:,k));
    signFlow=sign(median(flow(active,k)));if signFlow==0,signFlow=1;end
    significant=abs(flow(:,k))>=max(0.01*max(abs(flow(:,k))),1e-4);
    reverse(k)=mean(signFlow*flow(significant,k)<0);
    valid=active&shaft(:,k)>1;
    if nnz(valid)>=5,efficiency(k)=median(hydraulic(valid,k)./shaft(valid,k));end
end
feedAbs=abs(feed(:,1));feedRef=median(feedAbs(late));
availability=mean(feedAbs>=max(0.5*feedRef,1e-4));
total=tank(:,1)+tank(:,2)+tank(:,3);
loss=total(1)-total(end);integrated=trapz(t,feedAbs/920.027);
row.metrics=struct("native_profile",string(scenario.native_profile), ...
    "requested_wing_initial_volume_m3",double(scenario.wing_initial_volume_m3), ...
    "requested_center_initial_volume_m3",double(scenario.center_initial_volume_m3), ...
    "command_min_rpm",min(command,[],1),"command_max_rpm",max(command,[],1), ...
    "command_transition_count",sum(abs(diff(command))>30,1), ...
    "pump_tracking_nrmse",nrmse, ...
    "pump_command_speed_abs_correlation",correlation, ...
    "pump_measured_speed_range_rpm",ranges, ...
    "pump_reverse_flow_fraction",reverse, ...
    "pump_pressure_rise_mpa_late",median(pressure(late,:),1), ...
    "pump_mass_flow_kg_s_late",median(abs(flow(late,:)),1), ...
    "pump_shaft_power_w_late",median(shaft(late,:),1), ...
    "pump_hydraulic_power_w_late",median(hydraulic(late,:),1), ...
    "pump_efficiency_late",efficiency, ...
    "left_volume_start_m3",tank(1,1),"right_volume_start_m3",tank(1,2), ...
    "center_volume_start_m3",tank(1,3),"left_volume_end_m3",tank(end,1), ...
    "right_volume_end_m3",tank(end,2),"center_volume_end_m3",tank(end,3), ...
    "minimum_tank_volume_m3",min(tank(:,1:3),[],"all"), ...
    "maximum_center_volume_m3",max(tank(:,3)), ...
    "maximum_absolute_cg_offset_percent",max(abs(tank(:,4))), ...
    "engine_feed_mass_flow_kg_s_late",feedRef, ...
    "engine_feed_pressure_rise_mpa_late",median(feed(late,2)), ...
    "engine_feed_availability_fraction",availability, ...
    "engine_feed_dropout_fraction",1-availability, ...
    "total_fuel_volume_loss_m3",loss, ...
    "integrated_engine_delivery_m3",integrated, ...
    "inventory_balance_relative_residual",abs(loss-integrated)/ ...
        max(abs(integrated),0.05), ...
    "maximum_pump_restore_time_s",localRecovery(t,command,actual,true), ...
    "maximum_pump_shutdown_time_s",localRecovery(t,command,actual,false), ...
    "restore_event_count",sum(sum(diff(command)>300)), ...
    "shutdown_event_count",sum(sum(diff(command)<-300)), ...
    "late_tank_volume_relative_drift", ...
        (max(total(late))-min(total(late)))/ ...
        max(abs(mean(total(late))),1e-6), ...
    "finite_fraction",mean(isfinite([pump,tank,transfer,feed,power]),"all"));
row.outputs=outputs;row.offline_metrics=row.metrics;
row.valid=row.output_contract.all_required_pass&&row.metrics.finite_fraction>=0.999999;
end
function value=localRecovery(t,command,actual,rising)
times=[];for c=1:4
changes=find((diff(command(:,c))>300)==rising & abs(diff(command(:,c)))>300);
for i=reshape(changes,1,[]),target=command(i+1,c);
tol=max(0.08*abs(target),120);j=find(abs(actual(i+1:end,c)-target)<=tol,1);
if ~isempty(j),times(end+1)=t(i+j)-t(i+1);end %#ok<AGROW>
end,end
if isempty(times),value=0;else,value=max(times);end
end
function value=localCorr(a,b)
if std(a)<1e-12||std(b)<1e-12,value=0;else,c=corrcoef(a,b);value=abs(c(1,2));end
end
function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
audit=struct("required_products_available",true, ...
    "qualification_basis","public_multiscenario_behavior", ...
    "qualification_deferred_to_offline_public_behavior",true, ...
    "signal_cycle_observed",structure.signal_cycle_present, ...
    "physical_connection_block_count_observation", ...
        structure.physical_connection_block_count);
end
function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
    rows(k).width=widths(k);end
end
function [taskRoot,sharedRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end

function binding = localFilePresence(pathIn)
assert(isfile(pathIn), "SimuVerity:FileMissing", "Required file is missing: %s", pathIn);
binding = "present";
end

